```python
"""Append-only nogood log with CRC32 integrity checks and crash recovery."""

from __future__ import annotations

import json
import os
import struct
import zlib

_HEADER = struct.Struct(">I")   # payload length
_CRC = struct.Struct(">I")      # crc32 of payload


class ClauseFormatError(ValueError):
    """Raised when a clause JSON payload is malformed."""


def canonicalize_clause(clause):
    """Validate a nogood clause and return its canonical JSON string."""
    if not isinstance(clause, list) or not clause:
        raise ClauseFormatError("clause must be a non-empty JSON array of literals")
    for lit in clause:
        if not isinstance(lit, dict) or set(lit) != {"var", "value"}:
            raise ClauseFormatError("each literal must be an object with exactly 'var' and 'value'")
        if not isinstance(lit["var"], str) or not lit["var"]:
            raise ClauseFormatError("literal 'var' must be a non-empty string")
        value = lit["value"]
        if value is not None and not isinstance(value, (str, int, float, bool)):
            raise ClauseFormatError("literal 'value' must be a JSON scalar")
    return json.dumps(clause, sort_keys=True, separators=(",", ":"))


def parse_clause_json(text):
    try:
        clause = json.loads(text)
    except json.JSONDecodeError as exc:
        raise ClauseFormatError(f"invalid JSON: {exc}") from exc
    canonicalize_clause(clause)
    return clause


def encode_entry(clause):
    payload = canonicalize_clause(clause).encode("utf-8")
    crc = zlib.crc32(payload) & 0xFFFFFFFF
    return _HEADER.pack(len(payload)) + payload + _CRC.pack(crc)


class NogoodLog:
    def __init__(self, path):
        self.path = os.fspath(path)

    def append(self, clause):
        """Append one nogood; committed only after flush+fsync."""
        entry = encode_entry(clause)
        with open(self.path, "ab") as fh:
            fh.write(entry)
            fh.flush()
            os.fsync(fh.fileno())

    def load(self):
        """Sequentially parse; stop at first truncated/corrupt entry."""
        clauses = []
        try:
            fh = open(self.path, "rb")
        except FileNotFoundError:
            return clauses
        with fh:
            while True:
                header = fh.read(_HEADER.size)
                if len(header) == 0:
                    break  # clean EOF
                if len(header) < _HEADER.size:
                    break  # truncated header
                (length,) = _HEADER.unpack(header)
                payload = fh.read(length)
                if len(payload) < length:
                    break  # truncated payload
                crc_bytes = fh.read(_CRC.size)
                if len(crc_bytes) < _CRC.size:
                    break  # truncated crc
                (expected,) = _CRC.unpack(crc_bytes)
                if zlib.crc32(payload) & 0xFFFFFFFF != expected:
                    break  # checksum mismatch
                clauses.append(json.loads(payload.decode("utf-8")))
        return clauses
```

Note: should payload JSON be validated on load? CRC guarantees integrity of what was written, and append validates. But a tampered entry with recomputed CRC... out of scope. Keep it simple; maybe validate anyway — if invalid, stop. Actually if CRC matches, content is as-written, which was validated. Fine.

