class CSPSolver:
    def __init__(self, domains):
        self.domains = {v: list(d) for v, d in domains.items()}
        self.nogoods = []
        self._nogood_keys = set()
        self.pruned_nodes = 0

    @staticmethod
    def _key(clause):
        return frozenset((lit["var"], _freeze(lit["value"])) for lit in clause)

    def add_nogood(self, clause):
        key = self._key(clause)
        if key in self._nogood_keys:
            return False
        self._nogood_keys.add(key)
        self.nogoods.append(key)
        return True

    def add_nogoods(self, clauses):
        return sum(1 for c in clauses if self.add_nogood(c))

    def persist_nogood(self, log, clause):
        """Best-effort persistence; failures never affect search state."""
        try:
            log.append(clause)
        except OSError:
            return False
        return True

    def solve(self, max_solutions=None):
        variables = list(self.domains)
        assignment = {}
        solutions = []

        def violates(assignment):
            for nogood in self.nogoods:
                if all(assignment.get(var, _SENTINEL) == val for var, val in nogood):
                    return True
            return False

        def backtrack(idx):
            if idx == len(variables):
                solutions.append(dict(assignment))
                return
            var = variables[idx]
            for value in self.domains[var]:
                assignment[var] = value
                if violates(assignment):
                    self.pruned_nodes += 1
                else:
                    backtrack(idx + 1)
                del assignment[var]
                if max_solutions is not None and len(solutions) >= max_solutions:
                    return

        backtrack(0)
        return solutions
```

Wait — nogood pruning: a nogood is a set of assignments that can't all hold. If current partial assignment covers all literals of a nogood → prune. That's what violates does. Good.

_freeze: values are JSON scalars, hashable already. Just use value directly.

Note on `assignment.get(var, _SENTINEL) == val`: since we only assign vars in order and check after assigning, unassigned vars use sentinel. Fine.

**`csp_persist/__main__.py`** CLI:

```python
import argparse, json, sys
from .log import NogoodLog, ClauseFormatError, parse_clause_json

def main(argv=None):
    parser = argparse.ArgumentParser(prog="csp_persist", ...)
    sub = parser.add_subparsers(dest="command", required=True)
    for name in ("write", "load"):
        p = sub.add_parser(name)
        p.add_argument("--log", required=True)
        if name == "write":
            p.add_argument("--clause", required=True)
    args = parser.parse_args(argv)
    log = NogoodLog(args.log)
    if args.command == "write":
        try:
            clause = parse_clause_json(args.clause)
        except ClauseFormatError as exc:
            print(f"error: invalid clause: {exc}", file=sys.stderr)
            return 2
        try:
            log.append(clause)
        except OSError as exc:
            print(f"error: cannot write log: {exc}", file=sys.stderr)
            return 1
        print(json.dumps({"status": "committed", "log": log.path}))
        return 0
    else:
        clauses = log.load()
        print(json.dumps(clauses))
        return 0
```

