    """Reference implementation: plain sequential parse, independent of csp_persist."""
    import struct, zlib, json, os
    out = []
    if not os.path.exists(path):
        return out
    data = open(path, "rb").read()
    pos = 0
    while pos < len(data):
        if pos + 4 > len(data): break
        (n,) = struct.unpack(">I", data[pos:pos+4]); pos += 4
        if pos + n + 4 > len(data): break
        payload = data[pos:pos+n]; pos += n
        (crc,) = struct.unpack(">I", data[pos:pos+4]); pos += 4
        if zlib.crc32(payload) & 0xFFFFFFFF != crc: break
        out.append(json.loads(payload.decode("utf-8")))
    return out
